function columnControl(column,row,rowIndex,fieldId){const value=row?.[column.key]??'';const label=esc((column.name||'列')+' 第'+(rowIndex+1)+'行');
if(column.type==='select')return '<select data-table-cell="'+fieldId+'" data-row="'+rowIndex+'" data-column="'+column.key+'" aria-label="'+label+'"><option value="">请选择</option>'+M.options(column.options).map(o=>'<option value="'+esc(o)+'"'+(String(value)===o?' selected':'')+'>'+esc(o)+'</option>').join('')+'</select>';if(column.type==='multi')return multiPicker(fieldId+'-'+rowIndex+'-'+column.key, M.options(column.options), String(value).split(',').map(s=>s.trim()).filter(Boolean), label);
if(column.type==='textarea')return '<textarea data-table-cell="'+fieldId+'" data-row="'+rowIndex+'" data-column="'+column.key+'" aria-label="'+label+'">'+esc(value)+'</textarea>';
return '<input data-table-cell="'+fieldId+'" data-row="'+rowIndex+'" data-column="'+column.key+'" aria-label="'+label+'" value="'+esc(value)+'" placeholder="请输入">';}
function detailTableMarkup(f){const columns=f.columns||[],rows=Array.isArray(f.rows)&&f.rows.length?f.rows:[M.blankRow(columns)];
return '<div class="detail-table" data-detail-table="'+f.id+'"><div class="detail-toolbar"><span>'+rows.length+' 行</span>'+btn(icon('plus')+'新增行','add-table-row','','data-id="'+f.id+'"')+btn('删除所选','delete-table-rows','','data-id="'+f.id+'"')+'</div><div class="table-scroll"><table class="detail-grid"><thead><tr><th><input type="checkbox" data-table-select-all="'+f.id+'" aria-label="选择全部行"></th>'+columns.map(c=>'<th>'+(c.required?'<span class="required">*</span>':'')+esc(c.name)+'</th>').join('')+'<th>操作</th></tr></thead><tbody>'+rows.map((row,i)=>'<tr><td><input type="checkbox" data-table-row-check="'+f.id+'" data-row="'+i+'" aria-label="选择第'+(i+1)+'行"></td>'+columns.map(c=>'<td>'+columnControl(c,row,i,f.id)+'</td>').join('')+'<td>'+btn('删除','delete-table-row','link danger','data-id="'+f.id+'" data-row="'+i+'" aria-label="删除第'+(i+1)+'行"')+'</td></tr>').join('')+'</tbody></table></div><div class="table-errors" data-table-errors="'+f.id+'"></div></div>';}
function ensureTableRows(field){if(!Array.isArray(field.rows)||!field.rows.length)field.rows=[M.blankRow(field.columns||[])];}
function activeTableHost(){return d;}
function findTable(id){return (activeTableHost()?.working||d?.working)?.fields?.find(f=>f.id===id);}
function rerenderTableHost(){if(modalContext?.kind==='preview'){$('#modal .modal-body').innerHTML='<p class="small muted">基于当前未保存配置预览</p>'+previewSections(d.working)+'<div id="modal-error" class="error-note" role="alert"></div>';}else if(modalContext?.kind==='spu')renderSpu();}

