let d=null, modalContext=null, pending=null, returnFocus=null, dragged=null, stale=false;
const groupBy=id=>state.groups.find(g=>g.id===id);
const templateBy=id=>state.templates.find(t=>t.id===id);
const childBy=id=>state.groups.flatMap(g=>g.children).find(c=>c.id===id);
const now=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());
function toast(message,error=false){const el=document.createElement('div');el.className=`toast ${error?'error':''}`;el.innerHTML=icon(error?'info':'check')+esc(message);$('#toasts').append(el);setTimeout(()=>el.remove(),5000);}
function commit(transform){try{if(stale)throw Error('其他标签页已更新配置，请先刷新本页再继续保存');const next=transform(state);localStorage.setItem(STORE,JSON.stringify(next));state=next;renderList();return true;}catch(e){const message=e.name==='QuotaExceededError'?'浏览器存储空间不足，保存失败，请保留当前内容后清理存储空间':e.name==='SecurityError'?'浏览器禁止本地存储，修改未保存':e.message;toast(message,true);const target=$('#modal').open?$('#modal-error'):$('#editor-error');if(target)target.textContent=message;return false;}}
function groupOptions(selected='',empty=false){return (empty?'<option value="">请选择一级品线</option>':'')+state.groups.map(g=>`<option value="${esc(g.id)}" ${g.id===selected?'selected':''}>${esc(g.name)}</option>`).join('');}
function shell(){const title=view==='specs'?'产品规格书配置':'品线管理';$('#app').innerHTML=`
<aside class="sidebar"><div class="brand"><div class="brand-logo"><b>STAR</b>MERX</div><div class="brand-caption">星商品牌中心</div></div><div class="nav-label">WORKSPACE</div>${[['grid','工作台'],['folder','立项管理'],['box','商品管理'],['tag','品牌管理'],['file','翻译管理'],['layers','设计管理']].map(([i,n])=>`<div class="nav-item">${icon(i)}<span>${n}</span></div>`).join('')}<div class="nav-label">MANAGEMENT</div><div class="nav-item current">${icon('settings')}<span>基础配置</span></div><div class="nav-sub">审核流程</div><button class="nav-sub nav-control ${view==='lines'?'selected':''}" data-action="navigate" data-view="lines">品线管理</button><button class="nav-sub nav-control ${view==='specs'?'selected':''}" data-action="navigate" data-view="specs">产品规格书配置</button><div class="sidebar-foot">${icon('box')} 演示工作空间 · 本地保存</div></aside>
<div class="shell"><header class="topbar"><div class="topnav">${icon('grid')} 销售中心</div><div class="topnav active">${icon('layers')} 开发中心</div><div class="topnav">${icon('file')} 订单中心</div><div class="topnav">${icon('box')} 系统中心</div><span class="spacer"></span><span class="prototype-tag">交互设计原型</span><span class="avatar">演</span><span>演示用户</span></header><div class="breadcrumb">${icon('menu')}<span>首页</span><span>/</span><span>基础配置</span><span>/</span><span class="active">${title}</span></div><div class="page-tabs"><button class="page-tab ${view==='lines'?'active':''}" data-action="navigate" data-view="lines">品线管理</button><button class="page-tab ${view==='specs'?'active':''}" data-action="navigate" data-view="specs">产品规格书配置</button></div>
<main class="page"><div class="page-heading"><div><div class="row"><div class="title-icon">${icon(view==='specs'?'file':'layers')}</div><h1 class="page-title">${title}</h1></div><p class="subtitle">${view==='specs'?'统一管理规格书模板。一期在品线管理中关联规格书，可选择全部规格书。':'配置品线的规格书关联与主模板，明确新增 SPU 的默认使用规则。'}</p></div><div class="row page-actions"><a class="product-plan-link" href="product-plan.html" target="_blank" rel="noopener noreferrer">${icon('file')}产品方案</a>${btn(icon('eye')+'新增 SPU 演示','spu')}${view==='specs'?btn(icon('plus')+'新增规格书','new-spec','primary'):btn(icon('plus')+'新增二级品线','new-child','primary')}</div></div>
<div class="notice">${icon('info')}<div><strong>历史兼容：</strong>一级品线默认模板与现有老模板保持一致；二级品线初始化继承该模板作为主模板。后续新增 SPU 使用二级品线主模板，历史 SPU 数据不在本次调整范围。</div>${btn('初始化检查','initialization','link')}</div>${state.migration?`<div class="migration-note">${icon('check')}${esc(state.migration.notice)}</div>`:''}
<section class="table-card"><div class="filter-bar"><label class="search-wrap">${icon('search')}<input id="search" type="search" aria-label="${view==='specs'?'搜索规格书':'搜索品线'}" placeholder="${view==='specs'?'搜索规格书名称':'搜索品线名称 / 编码'}" value="${esc(filters.query)}"></label>${view==='lines'?'<select id="filter-group" aria-label="筛选一级品线"><option value="">全部一级品线</option>'+groupOptions(filters.group)+'</select>':''}${btn(icon('search')+'查询','search','primary')}${btn('重置','reset')}<span class="spacer"></span>${view==='lines'?btn('全部展开 / 收起','expand','ghost'):'<span class="muted small">按规格书名称管理 · 不再使用版本号</span>'}</div><div class="table-heading"><strong>${view==='specs'?'规格书列表':'品线配置列表'}</strong><span id="list-summary" class="muted small"></span></div><div class="table-scroll"><table class="tree-table ${view==='specs'?'spec-table':'line-table'}">${view==='lines'?'<colgroup><col class="col-index"><col class="col-name"><col class="col-code"><col class="col-link"><col class="col-category"><col class="col-owner"><col class="col-quality"><col class="col-supply"><col class="col-check"><col class="col-status"><col class="col-note"><col class="col-editor"><col class="col-time"><col class="col-action"></colgroup>':''}<thead>${view==='specs'?'<tr><th>规格书名称</th><th>备注</th><th>创建人</th><th>更新人</th><th>修改时间</th><th>操作</th></tr>':'<tr><th>#</th><th>品线名称</th><th>品线编码</th><th>已关联规格书</th><th>关联品类</th><th>品线负责人</th><th>品质负责人</th><th>供应链经理</th><th>是否需要产前样质检</th><th>状态</th><th>备注</th><th>修改人</th><th>修改时间</th><th>操作</th></tr>'}</thead><tbody id="listbody"></tbody></table></div><div class="table-foot"><span id="table-total"></span><span>所有记录均为演示数据</span></div></section><div class="page-note"><span>${icon('lock')}浏览器本地保存，不连接真实业务数据</span><span>SPECIFICATION TEMPLATE MANAGEMENT</span></div></main></div>`;renderList();}
function renderList(){if(!$('#listbody'))return;
const query=filters.query.toLowerCase();let rows='',count=0;
if(view==='specs'){const templates=state.templates.filter(t=>t.name.toLowerCase().includes(query));count=templates.length;rows=templates.map(t=>{const linked=M.specLines(state,t.id),usedDefault=state.groups.some(g=>g.defaultTemplateId===t.id);const remark=String(t.remark||'').trim();return`<tr><td><div class="template-name">${icon('file')}<strong>${esc(t.name)}</strong>${usedDefault?'<span class="badge outline">一级默认</span>':''}</div><div class="template-meta">${t.fields.length} 个字段<span>·</span>已被 ${linked.length} 个二级品线关联</div></td><td class="spec-remark ${remark?'':'is-empty'}">${remark?esc(remark):'--'}</td><td>${esc(t.creator)}</td><td>${esc(t.updater)}</td><td class="mono">${esc(t.updatedAt)}</td><td>${btn('编辑模板','edit-spec','link',`data-id="${esc(t.id)}"`)}</td></tr>`;}).join('');}
else{for(const g of state.groups){if(filters.group&&g.id!==filters.group)continue;const match=(g.name+' '+g.code).toLowerCase().includes(query);const children=g.children.filter(c=>match||(c.name+' '+c.code).toLowerCase().includes(query));if(query&&!match&&!children.length)continue;rows+=lineRecordRow(g,null,++count);
if(expanded.has(g.id)||query)for(const c of children)rows+=lineRecordRow(g,c,++count);}}
$('#listbody').innerHTML=rows||`<tr><td colspan="${view==='specs'?6:14}" class="table-empty">${icon('search')}<p>未找到匹配的${view==='specs'?'规格书':'品线'}</p><p class="small">请更换关键词或重置筛选</p></td></tr>`;$('#list-summary').textContent=view==='specs'?`${count} 个规格书`:`${count} 条品线记录`;$('#table-total').textContent=`共 ${count} 条记录`;}
function associationStatus(group,child){if(child)return '';if(group.defaultTemplateId&&templateBy(group.defaultTemplateId))return '<span class="badge teal">已关联</span>';return '<span class="badge">未关联</span><div class="link-alert">请配置'+esc(group.name)+'一级品线的规格书默认模板</div>';}
function lineRecordRow(group,child,index){const item=child||group,owner=item.updater||'演示用户';return '<tr'+(child?'':' class="group-row"')+'><td>'+index+'</td><td>'+(child?'<div class="child-name">'+icon('tag')+esc(child.name)+'</div>':'<div class="group-name">'+btn(icon(expanded.has(group.id)||filters.query?'down':'chevron'),'toggle','icon-btn','data-group="'+esc(group.id)+'" aria-label="展开或收起'+esc(group.name)+'"')+icon('layers')+esc(group.name)+'<span class="group-number">'+group.children.length+'</span></div>')+'</td><td class="mono">'+esc(item.code)+'</td><td>'+associationStatus(group,child)+'</td><td>--</td><td>'+esc(owner)+'</td><td>--</td><td>--</td><td>否</td><td><span class="badge teal">启用</span></td><td>--</td><td>'+esc(owner)+'</td><td class="mono">'+esc(item.updatedAt||'')+'</td><td>'+lineMenu(group.id,child&&child.id)+'</td></tr>';}
function renderLineConfig(){const ctx=modalContext,c=childBy(ctx.lineId),g=state.groups.find(g=>g.children.some(x=>x.id===c.id)),selected=state.templates.filter(t=>ctx.ids.includes(t.id));
if(ctx.picker){$('#modal .modal-body').innerHTML='<div class="config-context">'+icon('layers')+'<strong>选择规格书模板</strong></div><div class="notice">'+icon('info')+'勾选后确认，返回的列表只展示已选择、可供「'+esc(c.name)+'」使用的规格书。</div><table class="association-table"><thead><tr><th>选择</th><th>规格书名称</th></tr></thead><tbody>'+state.templates.map(t=>'<tr><td><input type="checkbox" data-template-select="'+esc(t.id)+'" aria-label="选择 '+esc(t.name)+'" '+(ctx.draftIds.includes(t.id)?'checked':'')+'></td><td>'+esc(t.name)+'</td></tr>').join('')+'</tbody></table><div id="modal-error" class="error-note" role="alert"></div>';$('#modal .modal-footer').innerHTML=btn('返回','back-spec-picker')+btn('确认选择','apply-spec-picker','primary');return;}
$('#modal .modal-body').innerHTML='<div class="config-context">'+icon('layers')+'<strong>'+esc(g.name)+' / '+esc(c.name)+'</strong><span class="mono">'+esc(c.code)+'</span>'+btn('选择规格书模板','pick-specs','')+'</div><table class="association-table"><thead><tr><th>规格书名称</th><th>是否主模板</th></tr></thead><tbody>'+(selected.map(t=>'<tr><td>'+esc(t.name)+(t.id===g.defaultTemplateId?'<span class="badge outline">一级默认</span>':'')+'</td><td><label class="primary-radio"><input type="radio" name="line-primary" value="'+esc(t.id)+'" aria-label="'+esc(t.name)+' 设为主模板" '+(ctx.primary===t.id?'checked':'')+'>设为主模板</label></td></tr>').join('')||'<tr><td colspan="2" class="table-empty">尚未选择可供'+esc(c.name)+'使用的规格书</td></tr>')+'</tbody></table><p class="small muted" style="margin-top:12px">以下为可用于「'+esc(c.name)+'」二级品线的规格书。主模板只能有一个。</p><div id="modal-error" class="error-note" role="alert"></div>';$('#modal .modal-footer').innerHTML=btn('取消','close-modal')+btn('保存配置','save-line','primary');}
function lineMenu(groupId,childId){return`<details class="line-menu"><summary aria-label="${esc(childId?childBy(childId).name:groupBy(groupId).name)} 操作">···</summary><div class="line-menu-items">${btn('销售属性配置','sales-info','ghost')}${btn('规格书配置',childId?'line-config':'group-config','ghost',`data-id="${esc(childId||groupId)}"`)}</div></details>`;}
function draftSnapshot(){return JSON.stringify({working:d.working,lineIds:[...d.lineIds].sort(),primaryChoices:d.primaryChoices});}
function openEditor(specId,_groupId,name){returnFocus=document.activeElement;const old=specId?templateBy(specId):null;d={working:old?M.clone(old):{id:M.uid(),groupId:null,name,remark:'',fields:M.baseFields()},lineIds:[],primaryChoices:{},tab:'basic',section:'fields',errors:[],isNew:!old,reuseFromId:'',reuseDraftId:''};if(d.working.remark==null)d.working.remark='';d.baseline=draftSnapshot();d.dirty=false;$('#overlay').hidden=false;$('#drawer').hidden=false;$('#app').inert=true;document.body.style.overflow='hidden';renderDrawer();$('#drawer [data-action="close-drawer"]').focus();}
