function markDirty(){d.dirty=draftSnapshot()!==d.baseline;d.errors=[];const s=$('#save-status');if(s){s.textContent=d.dirty?'有未保存的修改':'所有修改已保存';s.classList.toggle('dirty',d.dirty);}}
function reuseBar(){const candidates=state.templates.filter(t=>t.id!==d.working.id),selected=candidates.some(t=>t.id===d.reuseDraftId)?d.reuseDraftId:'',applied=d.reuseFromId&&templateBy(d.reuseFromId);return `<div class="editor-sections">${btn(icon('settings')+'字段配置','editor-section','active')}<div class="reuse-spec"><label for="reuse-spec">${icon('copy')}复用历史规格书</label><select id="reuse-spec" aria-label="选择历史规格书" ${candidates.length?'':'disabled'}><option value="">${candidates.length?'请选择历史规格书':'暂无其他规格书'}</option>${candidates.map(t=>`<option value="${esc(t.id)}" ${t.id===selected?'selected':''}>${esc(t.name)}</option>`).join('')}</select>${btn('复用字段','reuse-fields','',candidates.length?'':'disabled')}<p id="reuse-error" class="error-note reuse-error" role="alert"></p><p class="reuse-note">${applied?`当前字段和备注来自「${esc(applied.name)}」的配置快照，可继续修改。`:'选择一份历史规格书，复制其字段配置和备注到当前页后再修改。'}历史规格书不会改变。</p></div></div>`;}
function renderDrawer(){const t=d.working;$('#drawer').innerHTML=`<header class="drawer-header"><div><h2 id="drawer-title">${icon('settings')}${d.isNew?'新增规格书 · 配置模板':'编辑规格书模板'}</h2><div class="drawer-breadcrumb"><strong>${esc(t.name||'未命名规格书')}</strong></div></div>${btn(icon('close'),'close-drawer','icon-btn close','aria-label="关闭配置抽屉"')}</header><div class="drawer-scroll"><div class="version-panel"><div class="version-form"><div class="form-group"><label for="spec-name">规格书名称 <span class="required">*</span></label><input id="spec-name" value="${esc(t.name)}" maxlength="60" placeholder="请输入规格书名称"></div><div class="form-group spec-remark-field"><label for="spec-remark">备注</label><textarea id="spec-remark" maxlength="500" rows="2" placeholder="选填，便于备注该规格书的适用范围">${esc(t.remark||'')}</textarea><p class="small muted">选填，最多 500 字，用于说明适用范围，不参与必填校验。</p></div></div><p class="small muted" style="margin-top:10px">直接在本页填写规格书名称并配置字段，无需先弹窗。名称、字段名称、控件类型必填，备注选填；下拉类必须填写可选值，明细表格至少配置一列。保存后再到品线管理关联。也可选择历史规格书，复用其字段配置后再修改。</p></div>${reuseBar()}<div class="module-tabs" role="tablist" aria-label="字段模块">${M.MODULES.map(m=>`<button class="module-tab ${d.tab===m.id?'active':''}" data-action="tab" data-tab="${m.id}" role="tab" aria-selected="${d.tab===m.id}">${icon(m.icon)}${m.name}<span class="tab-count">${t.fields.filter(f=>f.module===m.id).length}</span></button>`).join('')}</div>${fieldModuleMarkup(t)}<div id="editor-error" class="error-note" role="alert"></div></div><footer class="drawer-footer"><span id="save-status" class="save-status ${d.dirty?'dirty':''}">${d.dirty?'有未保存的修改':d.isNew?'填写名称和字段后保存':'所有修改已保存'}</span><span class="spacer"></span>${btn(icon('eye')+'预览规格书','preview-fields','ghost')}${btn('取消','close-drawer')}${btn('保存模板','save','primary')}</footer>`;attachDrag();}
function fieldModuleMarkup(t){const module=M.MODULES.find(m=>m.id===d.tab),fields=t.fields.filter(f=>f.module===d.tab);return`<div class="module-toolbar"><div><h3>${module.name}<span class="badge">${fields.length} 个字段</span></h3><p>${module.description}</p></div></div><div class="field-table-wrap"><table class="field-table"><colgroup><col style="width:43px"><col style="width:23%"><col style="width:48px"><col style="width:18%"><col style="width:23%"><col style="width:19%"><col style="width:71px"></colgroup><thead><tr><th>排序</th><th>字段名称*</th><th>必填</th><th>控件类型*</th><th>可选值 / 附件规则</th><th>默认值</th><th>操作</th></tr></thead><tbody>${fields.map((f,i)=>fieldRow(f,i,fields.length)).join('')||'<tr><td colspan="7" class="table-empty">当前模块暂无字段</td></tr>'}</tbody></table></div>${btn(icon('plus')+'添加一个字段','add-field','add-field-row')}<div class="configuration-note">${icon('info')}拖动手柄或使用箭头排序；可选值用逗号、分号或换行分隔。附件支持 Excel / Word / PDF，单个不超过 90 MB。上传图片仅支持 jpg、jpeg、png，单张不超过 20 MB，并可限制数量。任填组合可新增多条，必填时可设置任填一项即可通过。</div>`;}

function associationMarkup(){const g=groupBy(d.working.groupId),t=d.working;return`<div class="notice" style="margin-top:18px">${icon('info')}<div>仅可关联「${esc(g.name)}」下的二级品线。先勾选关联，再设置是否主模板；新勾选默认为「否」，选择「是」将当前规格书设为该品线唯一主模板。若需取消现有主模板，请先在品线管理中设置其他主模板。</div></div><div class="association-group"><label><input type="checkbox" id="select-all-lines" ${g.children.length&&g.children.every(c=>d.lineIds.includes(c.id))?'checked':''}>${icon('layers')} ${esc(g.name)}</label><span>${d.lineIds.length} / ${g.children.length} 已关联</span></div><div class="table-scroll"><table class="association-table"><thead><tr><th>关联二级品线</th><th>当前主模板</th><th>是否设为该品线主模板</th></tr></thead><tbody>${g.children.map(c=>{const selected=d.lineIds.includes(c.id),primary=selected&&d.primaryChoices[c.id]===true;return`<tr><td><label><input type="checkbox" data-line-select="${esc(c.id)}" ${selected?'checked':''}>${esc(g.name)} / ${esc(c.name)}</label></td><td>${esc(templateBy(c.primaryTemplateId)?.name||'尚未配置')}${c.primaryTemplateId===t.id?'<span class="badge outline">当前规格书</span>':''}</td><td><select data-line-primary="${esc(c.id)}" aria-label="${esc(c.name)} 是否设为该品线主模板" ${selected?'':'disabled'}><option value="false" ${primary?'':'selected'}>否</option><option value="true" ${primary?'selected':''}>是</option></select>${!selected?'<div class="cell-note">勾选关联后可设置</div>':''}</td></tr>`;}).join('')||'<tr><td colspan="3" class="table-empty">该一级品线暂无二级品线，可先保存模板</td></tr>'}</tbody></table></div>`;}

function reuseFields(){const id=$('#reuse-spec')?.value,error=$('#reuse-error'),source=id&&templateBy(id);if(!source||source.id===d.working.id){if(error)error.textContent='请选择要复用的历史规格书';$('#reuse-spec')?.focus();return;}if(!Array.isArray(source.fields)||!source.fields.length){if(error)error.textContent='所选规格书没有可复用的字段';return;}const sourceId=source.id,sourceName=source.name;confirmModal('复用历史规格书字段？','将用「'+sourceName+'」的字段配置和备注覆盖当前内容。已填写的备注也会被覆盖。复制后可继续修改，历史规格书不会改变。','确认复用',()=>{const current=templateBy(sourceId);if(!current){toast('历史规格书已不存在，请重新选择',true);return;}const snapshot=JSON.stringify(current);let fields;try{fields=M.cloneFields(current.fields);}catch(e){toast(e.message,true);return;}if(JSON.stringify(current)!==snapshot){toast('复用失败，历史规格书未被修改',true);return;}d.working.fields=fields;d.working.name=M.copiedSpecName(current.name,d.working.name,state.templates.filter(t=>t.id!==d.working.id).map(t=>t.name));d.working.remark=String(current.remark||'');d.reuseFromId=current.id;d.reuseDraftId=current.id;d.errors=[];const first=d.working.fields.find(f=>M.MODULES.some(m=>m.id===f.module));if(first)d.tab=first.module;markDirty();renderDrawer();toast('已复用字段，历史规格书不会改变');$('#reuse-spec')?.focus();});}
function saveEditor(){d.errors=M.validate(d.working.fields);if(d.errors.length){d.section='fields';d.tab=d.errors[0].module;renderDrawer();toast(d.errors[0].message,true);$('#drawer .invalid')?.focus();return;}const ok=commit(current=>M.saveSpec(current,d.working,'演示用户',now()));if(ok){d.isNew=false;d.working=M.clone(templateBy(d.working.id));d.baseline=draftSnapshot();d.dirty=false;renderDrawer();toast('规格书已保存');}}
function moveField(id,delta){const fields=d.working.fields,local=fields.filter(f=>f.module===d.tab),index=local.findIndex(f=>f.id===id),target=local[index+delta];if(!target)return;const a=fields.findIndex(f=>f.id===id),b=fields.findIndex(f=>f.id===target.id);[fields[a],fields[b]]=[fields[b],fields[a]];markDirty();renderDrawer();}
function isReadonly(){return false;}

function fieldRow(f,i,count){const err=d.errors?.filter(e=>e.id===f.id)||[];const attr=p=>`data-field="${f.id}" data-prop="${p}" aria-label="${esc(f.name||'新字段')} ${p==='name'?'字段名称':p==='type'?'控件类型':p==='options'?'可选值':'默认值'}"`;const enumType=['select','multi'].includes(f.type),attachment=f.type==='attachment',table=f.type==='table';
return`<tr data-row="${f.id}"><td><div class="index"><span class="sort-handle" draggable="true" data-drag="${f.id}" title="拖动排序">${icon('grip')}</span>${i+1}</div></td><td><input ${attr('name')} value="${esc(f.name)}" placeholder="请输入名称" class="${err.length?'invalid':''}" maxlength="60">${err.length?`<div class="error-note">${esc(err[0].message)}</div>`:''}</td><td>${btn('','required',`switch ${f.required?'on':''}`,`data-id="${f.id}" role="switch" aria-checked="${f.required}" aria-label="${esc(f.name||'新字段')} 是否必填"`)}</td><td><select ${attr('type')}>${Object.entries(M.TYPES).map(([k,n])=>`<option value="${k}" ${f.type===k?'selected':''}>${n}</option>`).join('')}</select></td><td>${table?'<div class="table-rule"><strong>'+(f.columns||[]).length+' 列</strong><span>'+esc((f.columns||[]).map(c=>c.name||'未命名列').join('、')||'尚未配置列')+'</span>'+btn('配置表格列','configure-table','link','data-id="'+f.id+'"')+'</div>':attachment?attachmentRule():f.type==='image'?imageRule(f):f.type==='anyfill'?anyFillRule(f):enumType?`<textarea ${attr('options')} placeholder="选项一,选项二">${esc(f.options)}</textarea><div class="cell-note" data-options-note="${f.id}">${M.options(f.options).length} 个选项 · 用逗号分隔</div>`:'<span class="dash">—</span>'}</td><td>${table?'<span class="muted small">填写时逐行录入</span>':attachment||f.type==='image'?'<span class="muted small">不设置默认文件</span>':f.type==='anyfill'?'<span class="muted small">填写时逐条录入</span>':f.type==='select'?`<select ${attr('value')}><option value="">无默认值</option>${M.options(f.options).map(o=>`<option value="${esc(o)}" ${f.value===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input ${attr('value')} type="${f.type==='date'?'date':'text'}" ${f.type==='number'?'inputmode="decimal"':''} value="${esc(f.value)}" placeholder="${f.type==='multi'?'多个值用逗号分隔':'选填'}">`}</td><td><div class="field-controls">${btn(icon('up'),'move-up','icon-btn',`data-id="${f.id}" aria-label="上移${esc(f.name)}" ${i===0?'disabled':''}`)}${btn(icon('down'),'move-down','icon-btn',`data-id="${f.id}" aria-label="下移${esc(f.name)}" ${i===count-1?'disabled':''}`)}${btn(icon('trash'),'delete-field','icon-btn danger',`data-id="${f.id}" aria-label="删除${esc(f.name||'新字段')}"`)}</div></td></tr>`;}

function attachDrag(){const drawer=$('#drawer');drawer.ondragstart=e=>{const handle=e.target.closest('[data-drag]');if(!handle||isReadonly())return;dragged=handle.dataset.drag;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragged);handle.closest('tr').classList.add('dragging');};drawer.ondragover=e=>{const row=e.target.closest('[data-row]');if(row&&dragged){e.preventDefault();drawer.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));row.classList.add('drag-over');}};drawer.ondrop=e=>{const row=e.target.closest('[data-row]');if(!row||!dragged)return;e.preventDefault();const source=d.working.fields.findIndex(f=>f.id===dragged),target=d.working.fields.findIndex(f=>f.id===row.dataset.row);if(source>=0&&target>=0&&source!==target){const [f]=d.working.fields.splice(source,1);d.working.fields.splice(target,0,f);markDirty();}dragged=null;renderDrawer();};drawer.ondragend=()=>{dragged=null;drawer.querySelectorAll('.dragging,.drag-over').forEach(x=>x.classList.remove('dragging','drag-over'));};}

function openColumnDialog(fieldId){const field=d.working.fields.find(f=>f.id===fieldId);if(!Array.isArray(field.columns))field.columns=[];openModal('配置表格列','<div id="column-config"></div>',btn('使用产品主要部件预设','use-parts-preset')+btn('取消','close-modal')+btn('应用列配置','apply-columns','primary'),{kind:'columns',fieldId,baseline:JSON.stringify(field.columns)},true);renderColumnDialog();}
function renderColumnDialog(){const field=d.working.fields.find(f=>f.id===modalContext.fieldId);$('#column-config').innerHTML='<div class="notice">'+icon('info')+'<div>配置表头和列规则。部件示例数据不保存在模板中，填写规格书时逐行录入。</div></div><div class="table-scroll"><table class="association-table"><thead><tr><th>列名称</th><th>控件类型</th><th>必填</th><th>可选值 / 默认值</th><th>操作</th></tr></thead><tbody>'+(field.columns.map((c,i)=>'<tr><td><input data-column="'+c.id+'" data-column-prop="name" value="'+esc(c.name)+'" aria-label="列名称" maxlength="40"></td><td><select data-column="'+c.id+'" data-column-prop="type" aria-label="列控件类型">'+Object.entries(M.TYPES).filter(([k])=>!['table','image','anyfill'].includes(k)).map(([k,n])=>'<option value="'+k+'"'+(c.type===k?' selected':'')+'>'+n+'</option>').join('')+'</select></td><td><input type="checkbox" data-column="'+c.id+'" data-column-prop="required" '+(c.required?'checked':'')+' aria-label="列必填"></td><td>'+(['select','multi'].includes(c.type)?'<textarea data-column="'+c.id+'" data-column-prop="options" aria-label="列可选值">'+esc(c.options)+'</textarea>':'<span class="muted small">无需可选值</span>')+'</td><td>'+btn('上移','move-column','link','data-id="'+c.id+'" data-delta="-1"'+(i===0?' disabled':''))+btn('下移','move-column','link','data-id="'+c.id+'" data-delta="1"'+(i===field.columns.length-1?' disabled':''))+btn('删除','delete-column','link danger','data-id="'+c.id+'"')+'</td></tr>').join('')||'<tr><td colspan="5" class="table-empty">请至少配置一列</td></tr>')+'</tbody></table></div>'+btn(icon('plus')+'新增列','add-column');}
function applyColumns(){const field=d.working.fields.find(f=>f.id===modalContext.fieldId);const errors=[];field.columns.forEach(c=>{if(!c.name.trim())errors.push('列名称不能为空');});if(!field.columns.length)errors.push('明细表格至少配置一列');if(errors.length){$('#modal-error').textContent=errors[0];return;}field.rows=undefined;closeModal(true);markDirty();renderDrawer();toast('表格列已应用到当前模板，保存模板后生效');}

function attachmentRule(){return '<div class="attachment-rule"><strong>Excel / Word / PDF</strong><span>.xls、.xlsx、.doc、.docx、.pdf</span><span>单个附件 ≤ 90 MB</span></div>';}
function imageRule(f){const limit=M.imageLimit(f.maxCount)||'';return '<div class="attachment-rule"><strong>JPG / JPEG / PNG</strong><span>不区分大小写，单张 ≤ 20 MB</span><label class="image-limit">数量上限<input data-field="'+f.id+'" data-prop="maxCount" type="number" min="1" max="20" step="1" value="'+esc(limit)+'" aria-label="'+esc(f.name||'新字段')+' 图片数量上限"></label></div>';}
function anyFillRule(f){const placeholder=f.placeholder||M.ANYFILL_PLACEHOLDER;return '<div class="attachment-rule"><input data-field="'+f.id+'" data-prop="placeholder" value="'+esc(placeholder)+'" maxlength="80" placeholder="填写提示" aria-label="'+esc(f.name||'新字段')+' 填写提示"><label class="anyfill-option"><input type="checkbox" data-field="'+f.id+'" data-prop="anyOnePasses" '+(f.anyOnePasses!==false?'checked':'')+' aria-label="'+esc(f.name||'新字段')+' 任填一项即可通过必填">任填一项即可通过必填</label></div>';}
function fillField(id){return (d?.working?.fields||[]).find(f=>f.id===id)||modalContext?.selection?.fields?.find(f=>f.id===id);}
function anyFillValues(field){if(modalContext?.kind==='spu'){modalContext.anyfill=modalContext.anyfill||{};if(!Array.isArray(modalContext.anyfill[field.id])||!modalContext.anyfill[field.id].length)modalContext.anyfill[field.id]=[''];return modalContext.anyfill[field.id];}if(!Array.isArray(field.entries)||!field.entries.length)field.entries=[''];return field.entries;}
function paintAnyFillStatus(field,values){const el=document.querySelector('[data-anyfill-status="'+field.id+'"]');if(!el)return;const result=M.validateAnyFill(field,values);el.textContent=field.required?result.message:'非必填，可留空';el.classList.toggle('ok',Boolean(field.required&&result.ok));el.classList.toggle('bad',Boolean(field.required&&!result.ok));}
function anyFillControl(f){const values=anyFillValues(f),placeholder=esc(f.placeholder||M.ANYFILL_PLACEHOLDER),result=M.validateAnyFill(f,values);return '<div class="anyfill-list">'+values.map((value,index)=>'<div class="anyfill-row"><input data-anyfill="'+f.id+'" data-index="'+index+'" value="'+esc(value)+'" placeholder="'+placeholder+'" aria-label="'+esc(f.name||'填写项')+' 第'+(index+1)+'项">'+(index===values.length-1?btn('+','add-anyfill','anyfill-add','data-id="'+f.id+'" aria-label="新增一项"'):'')+(values.length>1?btn('删除','remove-anyfill','link','data-id="'+f.id+'" data-index="'+index+'" aria-label="删除第'+(index+1)+'项"'):'')+'</div>').join('')+'<p class="preview-help">'+(f.anyOnePasses!==false?'必填时填写任意一项即可通过。':'必填时需填写全部内容。')+'点击加号可新增一条。</p><div class="anyfill-status '+(f.required&&result.ok?'ok':f.required?'bad':'')+'" data-anyfill-status="'+f.id+'" role="status">'+(f.required?result.message:'非必填，可留空')+'</div></div>';}
function refreshFillHost(){if(modalContext?.kind==='preview'){$('#modal .modal-body').innerHTML='<p class="small muted">基于当前未保存配置预览</p>'+previewSections(d.working)+'<div id="modal-error" class="error-note" role="alert"></div>';}else if(modalContext?.kind==='spu')renderSpu();}
function validateSelectedImages(input){
  const status=$('#image-status-'+input.dataset.image),files=[...(input.files||[])];
  const error=files.length?M.validateImageSelection(files,Number(input.dataset.max)):'';
  input.setCustomValidity(error);input.setAttribute('aria-invalid',error?'true':'false');
  status.classList.toggle('error-note',Boolean(error));
  if(error){input.value='';status.textContent=error;return;}
  if(!files.length){status.textContent='';return;}
  status.textContent='已选择 '+files.length+' 张：'+files.map(file=>file.name).join('、')+' · 仅当前预览有效';
}

function multiPicker(id, options, selected, label){const chosen=new Set(selected||[]);const summary=[...chosen].join('、')||'请选择';return '<div class="multi-picker"><button type="button" class="multi-picker-toggle'+(chosen.size?'':' placeholder')+'" data-action="toggle-multi" aria-expanded="false" aria-label="'+esc(label)+'">'+esc(summary)+'</button><div class="multi-picker-panel" hidden>'+(options.map(o=>'<label><input type="checkbox" data-multi-option="'+esc(id)+'" value="'+esc(o)+'" '+(chosen.has(o)?'checked':'')+'>'+esc(o)+'</label>').join('')||'<span class="muted small">暂无选项</span>')+'</div></div>';}
function placeMultiPanel(button, panel){const rect=button.getBoundingClientRect(),below=window.innerHeight-rect.bottom;panel.style.position='fixed';panel.style.left=Math.max(8,rect.left)+'px';panel.style.width=Math.min(rect.width,window.innerWidth-16)+'px';panel.style.zIndex='40';if(below<180&&rect.top>below){panel.style.top='auto';panel.style.bottom=(window.innerHeight-rect.top+4)+'px';}else{panel.style.bottom='auto';panel.style.top=(rect.bottom+4)+'px';}}
function closeMultiPanels(){document.querySelectorAll('.multi-picker-panel').forEach(panel=>{panel.hidden=true;panel.previousElementSibling?.setAttribute('aria-expanded','false');});}
function previewField(f){const common=`id="preview-f-${f.id}" ${f.required?'required':''}`,label=`<label for="preview-f-${f.id}">${esc(f.name)}${f.required?'<span class="required">*</span>':''}</label>`;let control;
if(f.type==='attachment'){control=`<div class="attachment-control"><input ${common} type="file" accept="${M.ATTACHMENT_ACCEPT}" data-attachment="${f.id}" aria-describedby="attachment-help-${f.id} attachment-status-${f.id}"><p id="attachment-help-${f.id}" class="preview-help">支持 Excel / Word / PDF（.xls、.xlsx、.doc、.docx、.pdf），单个文件不超过 90 MB。仅本地选择演示，不上传或保存附件。</p><div id="attachment-status-${f.id}" class="attachment-status" role="status" aria-live="polite"></div><button type="button" class="link" data-action="remove-attachment" data-id="${f.id}" hidden>移除附件</button></div>`;}
else if(f.type==='image'){const limit=M.imageLimit(f.maxCount)||5;control=`<div class="attachment-control"><input ${common} type="file" accept="${M.IMAGE_ACCEPT}" ${limit>1?'multiple':''} data-image="${f.id}" data-max="${limit}" aria-describedby="image-help-${f.id} image-status-${f.id}"><p id="image-help-${f.id}" class="preview-help">只能上传 jpg、jpeg、png（不区分大小写），单张不超过 20 MB，最多 ${limit} 张。仅本地选择演示，不上传或保存图片。</p><div id="image-status-${f.id}" class="attachment-status" role="status" aria-live="polite"></div></div>`;}
else if(f.type==='anyfill'){control=anyFillControl(f);}
else if(f.type==='select'){control=`<select ${common}><option value="">请选择</option>${M.options(f.options).map(o=>`<option ${f.value===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`;}
else if(f.type==='multi'){control=multiPicker('field-'+f.id, M.options(f.options), M.options(f.value), f.name)+'<span class="preview-help">点击展开后可多选，默认收起</span>';}
else if(f.type==='table'){ensureTableRows(f);control=detailTableMarkup(f);}
else if(f.type==='textarea')control=`<textarea ${common} placeholder="请输入${esc(f.name)}">${esc(f.value)}</textarea>`;else control=`<input ${common} type="${f.type==='number'?'number':f.type==='date'?'date':'text'}" value="${esc(f.value)}" placeholder="请输入${esc(f.name)}">`;return `<div class="form-group ${f.type==='table'?'table-field':''}">${label}${control}</div>`;}
function validateSelectedAttachment(input){
  const status=$('#attachment-status-'+input.dataset.attachment),remove=input.parentElement.querySelector('[data-action="remove-attachment"]'),file=input.files?.[0];
  const error=file?M.validateAttachment(file):'';input.setCustomValidity(error);input.setAttribute('aria-invalid',error?'true':'false');
  status.classList.toggle('error-note',Boolean(error));remove.hidden=true;
  if(error){input.value='';status.textContent=error;return;}
  if(!file){status.textContent='';return;}
  status.textContent='已选择：'+file.name+'（'+(file.size/(1024*1024)).toFixed(2)+' MB） · 仅当前预览有效';remove.hidden=false;
}

function openModal(title,body,footer,context={kind:'info'},wide=false){const modal=$('#modal');if(modal.open)modal.close();modalContext=context;modalContext.baseline=JSON.stringify(context);modal.className=wide?'preview-dialog':'';modal.setAttribute('aria-labelledby','modal-title');modal.innerHTML=`<header class="modal-header"><h2 id="modal-title">${title}</h2>${btn(icon('close'),'close-modal','icon-btn','aria-label="关闭弹窗"')}</header><div class="modal-body">${body}<div id="modal-error" class="error-note" role="alert"></div></div><footer class="modal-footer">${footer}</footer>`;modal.showModal();}
function modalDirty(){if(!modalContext)return false;const {baseline,...current}=modalContext;return ['line','group','new-spec','new-child'].includes(current.kind)&&JSON.stringify(current)!==baseline;}
function closeModal(force=false){if(!force&&modalDirty()&&!window.confirm('放弃弹窗中未保存的修改？'))return;$('#modal').close();modalContext=null;pending=null;}
function confirmModal(title,message,label,fn){openModal(title,`<p class="confirm-message">${esc(message)}</p>`,btn('取消','close-modal')+btn(label,'confirm','primary'),{kind:'confirm'});pending=fn;}
function newSpecDialog(){openModal('新增产品规格书',`<div class="notice">${icon('info')}规格书是独立模板，创建时不绑定一级品线。名称必填且不能重复；确认后进入字段配置，至少保留一个字段。字段名称和控件类型必填，下拉类必须填写可选值。</div><div class="form-group"><label for="new-spec-name">规格书名称 <span class="required">*</span></label><input id="new-spec-name" placeholder="如：家电出口规格书" maxlength="60"></div> `,btn('取消','close-modal')+btn('继续配置字段','create-spec','primary'),{kind:'new-spec',name:'',group:''});}
function createSpec(){const name=$('#new-spec-name').value.trim();if(!name){$('#modal-error').textContent='请填写规格书名称';return;}if(state.templates.some(t=>t.name.trim().toLowerCase()===name.toLowerCase())){$('#modal-error').textContent='已存在同名规格书';return;}closeModal(true);openEditor(null,null,name);}
function openLineConfig(id){const c=childBy(id);openModal('规格书配置','<div id="line-config"></div>','',{kind:'line',lineId:id,ids:[...c.templateIds],draftIds:[...c.templateIds],primary:c.primaryTemplateId,picker:false},true);renderLineConfig();}
function openGroupConfig(id){const g=groupBy(id);openModal(esc(g.name)+'-一级品线默认规格书',`<div class="notice notice-warn">${icon('info')}从全部规格书中选择一级默认模板。之后新增的二级品线会继承该规格书，并把它设为唯一主模板；不会覆盖已有二级主模板。</div><div class="form-group"><label for="group-default">一级品线默认模板 <span class="required">*</span></label><select id="group-default"><option value="">请选择默认规格书</option>${state.templates.map(t=>`<option value="${esc(t.id)}" ${t.id===g.defaultTemplateId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div>`,btn('取消','close-modal')+btn('保存默认模板','save-group','primary'),{kind:'group',groupId:id,templateId:g.defaultTemplateId});}
function newChildDialog(){const group=filters.group||state.groups[0]?.id;openModal('新增二级品线',`<div class="form-group"><label for="child-parent">所属一级品线</label><select id="child-parent">${groupOptions(group)}</select></div><div class="form-group" style="margin-top:16px"><label for="child-name">二级品线名称 <span class="required">*</span></label><input id="child-name" maxlength="40" placeholder="请输入二级品线名称"></div><div id="child-inherit" class="notice" style="margin-top:16px"></div>`,btn('取消','close-modal')+btn('创建并继承主模板','create-child','primary'),{kind:'new-child',groupId:group,name:''});updateChildNote();}
function updateChildNote(){const g=groupBy($('#child-parent').value);$('#child-inherit').textContent='创建后自动关联并设为主模板：'+(templateBy(g.defaultTemplateId)?.name||'尚未设置，请先配置一级默认模板');}
function initializationDialog(){const report=M.initializationReport(state);openModal('上线初始化检查',`<div class="notice">${icon('info')}先配置与老模板一致的规格书并设为一级默认，再补齐未关联的二级品线。初始化不改写历史 SPU，不覆盖人工配置的主模板。</div><div class="init-stats"><div><b>${report.ready.length}</b>已配置，无需处理</div><div><b>${report.pending.length}</b>待继承一级默认</div><div><b>${report.blocked.length}</b>需人工处理</div></div>${report.blocked.map(x=>`<p class="error-note">${esc(x.groupName)} / ${esc(x.name)}：${esc(x.message)}</p>`).join('')}${report.pending.map(x=>`<p>${esc(x.groupName)} / ${esc(x.name)} → 继承一级默认模板</p>`).join('')}<p class="small muted">可重复执行，仅补齐缺失关联；建议上线前核对字段与老模板一致，再执行真实迁移脚本。本按钮仅修改浏览器演示数据。</p>`,btn('关闭','close-modal')+btn(report.pending.length?'补齐缺失配置':'无需补齐','initialize','primary',report.blocked.length||!report.pending.length?'disabled':''),{kind:'init'});}
function previewSections(template){return M.MODULES.map(m=>`<section class="preview-module"><h3>${m.name}</h3><div class="preview-fields">${template.fields.filter(f=>f.module===m.id).map(previewField).join('')||'<p class="muted small">暂无字段</p>'}</div></section>`).join('');}
function openSpu(){const g=state.groups[0];openModal('新增 SPU · 规格书选择演示','<div id="spu-content"></div>',`<span class="small muted" style="margin-right:auto">仅演示选择与填写，不提交生产数据</span>${btn('关闭演示','close-modal')}`,{kind:'spu',groupId:g?.id,childId:g?.children[0]?.id,templateId:null},true);renderSpu();}
function renderSpu(){const ctx=modalContext,g=groupBy(ctx.groupId),c=g?.children.find(c=>c.id===ctx.childId);let selection,message='';try{if(c)selection=M.spuSelection(state,c.id,ctx.templateId);}catch(e){message=e.message;}if(selection)ctx.selection=selection.selected;
$('#spu-content').innerHTML=`<div class="notice">${icon('info')}新建 SPU 默认沿用二级品线主模板；其他可选项仅限该品线已关联的规格书。切换品线或模板将重新载入默认值。</div><div class="preview-selects"><div class="form-group"><label for="spu-group">一级品线</label><select id="spu-group">${groupOptions(ctx.groupId)}</select></div><div class="form-group"><label for="spu-child">二级品线</label><select id="spu-child">${g?.children.map(c=>`<option value="${esc(c.id)}" ${c.id===ctx.childId?'selected':''}>${esc(c.name)}</option>`).join('')||'<option value="">暂无二级品线</option>'}</select></div><div class="form-group"><label for="spu-template">规格书模板</label><select id="spu-template">${selection?.templates.map(t=>`<option value="${esc(t.id)}" ${t.id===selection.selected.id?'selected':''}>${esc(t.name)}${t.id===selection.primaryTemplateId?'（主模板）':''}</option>`).join('')||'<option value="">暂无可用规格书</option>'}</select></div></div>${selection?`<div class="spu-summary"><span class="badge ${selection.selected.id===selection.primaryTemplateId?'teal':'blue'}">${selection.selected.id===selection.primaryTemplateId?'默认使用主模板':'已切换关联模板'}</span><strong>${esc(selection.selected.name)}</strong><span class="small muted">一级默认：${esc(templateBy(g.defaultTemplateId)?.name||'未配置')}</span></div>${previewSections(selection.selected)}`:`<div class="table-empty">${esc(message||'暂无可用二级品线，请先在品线管理中配置。')}</div>`}`;}
document.addEventListener('click',e=>{if(!e.target.closest('.multi-picker'))closeMultiPanels();const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;
if(action==='configure-table')openColumnDialog(b.dataset.id);
else if(action==='use-parts-preset'){const field=d.working.fields.find(f=>f.id===modalContext.fieldId);field.columns=M.productPartsColumns();field.rows=undefined;closeModal(true);markDirty();renderDrawer();}
else if(action==='add-column'){const field=d.working.fields.find(f=>f.id===modalContext.fieldId);field.columns=field.columns||[];field.columns.push(M.newColumn(field.columns));renderColumnDialog();}
else if(action==='delete-column'){const field=d.working.fields.find(f=>f.id===modalContext.fieldId);field.columns=field.columns.filter(c=>c.id!==b.dataset.id);renderColumnDialog();}
else if(action==='move-column'){const field=d.working.fields.find(f=>f.id===modalContext.fieldId),i=field.columns.findIndex(c=>c.id===b.dataset.id),j=i+Number(b.dataset.delta);if(j>=0&&j<field.columns.length)[field.columns[i],field.columns[j]]=[field.columns[j],field.columns[i]];renderColumnDialog();}
else if(action==='apply-columns')applyColumns();
else if(action==='add-table-row'){const field=findTable(b.dataset.id);if(!field)return;ensureTableRows(field);field.rows.push(M.blankRow(field.columns||[]));rerenderTableHost();}
else if(action==='delete-table-row'){const field=findTable(b.dataset.id);if(!field)return;ensureTableRows(field);field.rows.splice(Number(b.dataset.row),1);if(!field.rows.length)field.rows=[M.blankRow(field.columns||[])];rerenderTableHost();}
else if(action==='delete-table-rows'){const field=findTable(b.dataset.id);if(!field)return;const selected=[...document.querySelectorAll('[data-table-row-check="'+b.dataset.id+'"]:checked')].map(x=>Number(x.dataset.row));field.rows=field.rows.filter((_,i)=>!selected.includes(i));if(!field.rows.length)field.rows=[M.blankRow(field.columns||[])];rerenderTableHost();}
else if(action==='remove-attachment'){const input=$(`[data-attachment="${b.dataset.id}"]`);input.value='';validateSelectedAttachment(input);}
else if(action==='add-anyfill'){const field=fillField(b.dataset.id);anyFillValues(field).push('');refreshFillHost();}
else if(action==='remove-anyfill'){const field=fillField(b.dataset.id),values=anyFillValues(field);values.splice(Number(b.dataset.index),1);if(!values.length)values.push('');refreshFillHost();}
else if(action==='navigate'){view=b.dataset.view;filters={query:'',group:''};shell();}
else if(action==='search'){filters.query=$('#search').value.trim();filters.group=$('#filter-group')?.value||'';renderList();}
else if(action==='reset'){filters={query:'',group:''};$('#search').value='';if($('#filter-group'))$('#filter-group').value='';renderList();}
else if(action==='toggle'){expanded.has(b.dataset.group)?expanded.delete(b.dataset.group):expanded.add(b.dataset.group);renderList();}
else if(action==='expand'){expanded=state.groups.every(g=>expanded.has(g.id))?new Set():new Set(state.groups.map(g=>g.id));renderList();}
else if(action==='new-spec'){openEditor(null,null,'');$('#spec-name')?.focus();}
else if(action==='create-spec')createSpec();
else if(action==='edit-spec')openEditor(b.dataset.id);
else if(action==='close-drawer')closeDrawer();
else if(action==='editor-section'){d.section=b.dataset.section;renderDrawer();}
else if(action==='reuse-fields')reuseFields();
else if(action==='tab'){d.tab=b.dataset.tab;renderDrawer();$(`#drawer [data-tab="${d.tab}"]`).focus();}
else if(action==='add-field'){d.working.fields.push(M.newField(d.working.fields,d.tab));markDirty();renderDrawer();$('#drawer .field-table tbody tr:last-child input')?.focus();}
else if(action==='required'){const f=d.working.fields.find(f=>f.id===b.dataset.id);f.required=!f.required;markDirty();renderDrawer();}
else if(action==='move-up'||action==='move-down')moveField(b.dataset.id,action==='move-up'?-1:1);
else if(action==='toggle-multi'){e.stopPropagation();const panel=b.parentElement.querySelector('.multi-picker-panel'),open=panel.hidden;closeMultiPanels();if(open){panel.hidden=false;b.setAttribute('aria-expanded','true');placeMultiPanel(b,panel);}return;}
else if(action==='delete-field'){e.stopPropagation();const id=b.dataset.id;if(!id)return;d.working.fields=d.working.fields.filter(x=>x.id!==id);markDirty();renderDrawer();$('#overlay').hidden=false;$('#drawer').hidden=false;}
else if(action==='save')saveEditor();
else if(action==='preview-fields')openModal('规格书表单预览',`<p class="small muted">基于当前未保存配置预览</p>${previewSections(d.working)}`,btn('关闭预览','close-modal'),{kind:'preview'},true);
else if(action==='pick-specs'){modalContext.picker=true;modalContext.draftIds=[...modalContext.ids];renderLineConfig();}
else if(action==='apply-spec-picker'){modalContext.ids=[...modalContext.draftIds];if(!modalContext.ids.includes(modalContext.primary))modalContext.primary=null;modalContext.picker=false;renderLineConfig();}
else if(action==='back-spec-picker'){modalContext.picker=false;renderLineConfig();}
else if(action==='line-config'){b.closest('details').open=false;openLineConfig(b.dataset.id);}
else if(action==='group-config'){b.closest('details').open=false;openGroupConfig(b.dataset.id);}
else if(action==='sales-info'){b.closest('details').open=false;openModal('销售属性配置','<p>此入口在现有系统中保持不变。本原型仅演示新增的「规格书配置」，未连接真实销售属性数据。</p>',btn('关闭','close-modal'));}
else if(action==='save-line'){const ctx=modalContext;if(commit(s=>M.configureLine(s,ctx.lineId,ctx.ids,ctx.primary,'演示用户',now()))){closeModal(true);toast('品线关联及主模板已保存');}}
else if(action==='save-group'){const ctx=modalContext;if(!ctx.templateId){$('#modal-error').textContent='请选择一级默认模板';return;}if(commit(s=>M.setGroupDefault(s,ctx.groupId,ctx.templateId,'演示用户',now()))){closeModal(true);toast('一级默认模板已保存，已有二级主模板不变');}}
else if(action==='new-child')newChildDialog();
else if(action==='create-child'){const ctx=modalContext;if(commit(s=>M.createLine(s,ctx.groupId,ctx.name,'演示用户',now()))){expanded.add(ctx.groupId);closeModal(true);renderList();toast('二级品线已创建，并继承一级默认模板');}}
else if(action==='initialization')initializationDialog();
else if(action==='initialize'){if(commit(s=>M.initializeLinks(s,'初始化',now()))){closeModal(true);toast('缺失关联已补齐，已有配置及历史 SPU 未改动');}}
else if(action==='spu')openSpu();
else if(action==='close-modal')closeModal();
else if(action==='confirm'){const fn=pending;closeModal(true);fn?.();}
});
document.addEventListener('input',e=>{const t=e.target;if(t.matches('[data-column]')){const field=d.working.fields.find(f=>f.id===modalContext.fieldId),column=field.columns.find(c=>c.id===t.dataset.column);column[t.dataset.columnProp]=t.type==='checkbox'?t.checked:t.value;return;}if(t.matches('[data-table-cell]')){const field=findTable(t.dataset.tableCell);ensureTableRows(field);field.rows[Number(t.dataset.row)][t.dataset.column]=t.value;return;}if(t.matches('[data-anyfill]')){const field=fillField(t.dataset.anyfill);const values=anyFillValues(field);values[Number(t.dataset.index)]=t.value;paintAnyFillStatus(field,values);return;}if(t.matches('[data-field]')&&d){const f=d.working.fields.find(f=>f.id===t.dataset.field);if(!f)return;if(t.dataset.prop==='anyOnePasses'){f.anyOnePasses=t.checked;markDirty();return;}if(t.dataset.prop==='maxCount'){f.maxCount=t.value;markDirty();return;}f[t.dataset.prop]=t.value;markDirty();if(t.dataset.prop==='options'){const note=$(`[data-options-note="${f.id}"]`);if(note)note.textContent=`${M.options(f.options).length} 个选项`;if(f.type==='select'){const select=$(`[data-field="${f.id}"][data-prop="value"]`);select.innerHTML='<option value="">无默认值</option>'+M.options(f.options).map(o=>`<option value="${esc(o)}" ${f.value===o?'selected':''}>${esc(o)}</option>`).join('');if(f.value&&!M.options(f.options).includes(f.value)){f.value='';select.value='';}markDirty();}}}
else if(t.id==='spec-name'){d.working.name=t.value;markDirty();}else if(t.id==='spec-remark'){d.working.remark=t.value;markDirty();}
else if(t.id==='reuse-spec'){d.reuseDraftId=t.value;const err=$('#reuse-error');if(err)err.textContent='';}
else if(t.id==='new-spec-name')modalContext.name=t.value;
else if(t.id==='child-name')modalContext.name=t.value;
});
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-multi-option]')){const picker=t.closest('.multi-picker'),selected=[...picker.querySelectorAll('input:checked')].map(x=>x.value),toggle=picker.querySelector('.multi-picker-toggle');toggle.textContent=selected.join('、')||'请选择';toggle.classList.toggle('placeholder',!selected.length);return;}
if(t.matches('[data-attachment]')){validateSelectedAttachment(t);}
else if(t.matches('[data-image]')){validateSelectedImages(t);}
else if(t.matches('[data-column-prop="type"]')){const field=d.working.fields.find(f=>f.id===modalContext.fieldId),column=field.columns.find(c=>c.id===t.dataset.column);column.type=t.value;column.value='';renderColumnDialog();}
else if(t.matches('[data-table-select-all]')){document.querySelectorAll('[data-table-row-check="'+t.dataset.tableSelectAll+'"]').forEach(x=>x.checked=t.checked);}
else if(t.matches('[data-prop="type"]')){const f=d.working.fields.find(f=>f.id===t.dataset.field);f.type=t.value;f.value='';if(f.type==='image'&&!M.imageLimit(f.maxCount))f.maxCount=5;if(f.type==='anyfill'){if(typeof f.anyOnePasses!=='boolean')f.anyOnePasses=true;if(!f.placeholder)f.placeholder=M.ANYFILL_PLACEHOLDER;}markDirty();renderDrawer();}
else if(t.id==='filter-group'){filters.group=t.value;filters.query=$('#search').value.trim();renderList();}
else if(t.matches('[data-line-select]')){d.lineIds=t.checked?[...new Set([...d.lineIds,t.dataset.lineSelect])]:d.lineIds.filter(id=>id!==t.dataset.lineSelect);if(t.checked)d.primaryChoices[t.dataset.lineSelect]=false;else delete d.primaryChoices[t.dataset.lineSelect];markDirty();renderDrawer();}
else if(t.id==='select-all-lines'){const ids=t.checked?groupBy(d.working.groupId).children.map(c=>c.id):[];d.primaryChoices=Object.fromEntries(ids.map(id=>[id,d.lineIds.includes(id)?d.primaryChoices[id]===true:false]));d.lineIds=ids;markDirty();renderDrawer();}
else if(t.matches('[data-line-primary]')){if(d.lineIds.includes(t.dataset.linePrimary))d.primaryChoices[t.dataset.linePrimary]=t.value==='true';markDirty();}
else if(t.matches('[data-template-select]')){const id=t.dataset.templateSelect,key=modalContext.picker?'draftIds':'ids';modalContext[key]=t.checked?[...new Set([...modalContext[key],id])]:modalContext[key].filter(x=>x!==id);if(!modalContext.picker&&!t.checked&&modalContext.primary===id)modalContext.primary=null;}
else if(t.name==='line-primary')modalContext.primary=t.value;
else if(t.id==='group-default')modalContext.templateId=t.value;
else if(t.id==='child-parent'){modalContext.groupId=t.value;updateChildNote();}
else if(t.id==='spu-group'){modalContext.groupId=t.value;modalContext.childId=groupBy(t.value)?.children[0]?.id;modalContext.templateId=null;modalContext.anyfill={};renderSpu();}
else if(t.id==='spu-child'){modalContext.childId=t.value;modalContext.templateId=null;modalContext.anyfill={};renderSpu();}
else if(t.id==='spu-template'){modalContext.templateId=t.value;modalContext.anyfill={};renderSpu();}
else if(t.id==='reuse-spec'){d.reuseDraftId=t.value;const err=$('#reuse-error');if(err)err.textContent='';}
});
$('#overlay').addEventListener('click',closeDrawer);
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='search'){$('[data-action="search"]').click();return;}if(!d||$('#modal').open)return;if(e.key==='Escape'){e.preventDefault();closeDrawer();return;}if(e.key==='Tab'){const items=[...$('#drawer').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)')].filter(x=>x.getClientRects().length);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('beforeunload',e=>{if(d?.dirty||modalDirty()){e.preventDefault();e.returnValue='';}});
window.addEventListener('storage',e=>{if(e.key===STORE){stale=true;toast('其他标签页已更新数据，请刷新本页后再保存，避免覆盖他人修改',true);}});
try{const saved=localStorage.getItem(STORE),legacy=localStorage.getItem(LEGACY_STORE);state=saved?M.upgradeTemplates(JSON.parse(saved)):legacy?M.upgradeTemplates(JSON.parse(legacy)):M.seedTemplates();if(!saved&&legacy){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{state.migration.notice+=' 新存储写入失败，请勿关闭页面；原数据仍保留。';}}shell();}
catch(e){$('#app').innerHTML=`<main style="padding:50px;max-width:800px;margin:auto"><h1>本地配置暂时无法读取</h1><p style="margin-top:18px">原数据未被清除或覆盖。请保留浏览器数据并联系维护人员，或使用新的浏览器会话查看演示。</p><p class="error-note">${esc(e.message)}</p><a href="product-plan.html" target="_blank" rel="noopener">查看产品方案</a></main>`;}

document.addEventListener("toggle",e=>{if(!e.target.matches?.(".line-menu")||!e.target.open)return;document.querySelectorAll(".line-menu[open]").forEach(x=>{if(x!==e.target)x.open=false;});const rect=e.target.querySelector("summary").getBoundingClientRect(),menu=e.target.querySelector(".line-menu-items");menu.style.left=Math.max(10,Math.min(window.innerWidth-160,rect.right-150))+"px";menu.style.top=(rect.bottom+100>window.innerHeight?Math.max(10,rect.top-90):rect.bottom+4)+"px";},true);
